const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const brazil = ee.FeatureCollection('FAO/GAUL/2015/level0')
      .filter(ee.Filter.eq('ADM0_NAME', 'Brazil'))
      .geometry();

    if (brazil.coordinates().length === 0) {
      console.log("Error: Could not retrieve Brazil's geometry.");
      console.log("C3"); // Calculation failure, as geometry is fundamental
      return;
    }

    const startYear2007 = '2007-01-01';
    const endYear2007 = '2007-12-31';
    const startYear2019 = '2019-01-01';
    const endYear2019 = '2019-12-31';

    // 2. Data Acquisition
    // Using MODIS/051/MCD14ML for fire detections, which is a FeatureCollection
    // Each feature represents a fire detection point.
    const firesCollection = ee.FeatureCollection('MODIS/051/MCD14ML');

    // Filter for 2007
    const fires2007 = firesCollection
      .filterDate(startYear2007, endYear2007)
      .filterBounds(brazil);

    const count2007 = await fires2007.size().getInfo();

    // Filter for 2019
    const fires2019 = firesCollection
      .filterDate(startYear2019, endYear2019)
      .filterBounds(brazil);

    const count2019 = await fires2019.size().getInfo();

    // Check for C1: Empty Collection
    if (count2007 === 0 && count2019 === 0) {
      console.log(`Fires 2007: ${count2007}, Fires 2019: ${count2019}`);
      console.log("C1"); // No fire detections found for either year
      return;
    }

    // 3. Processing and Calculation
    // No specific pixel masking needed as this is a point feature collection.
    // The count of features is the count of fire detections.

    // 4. Validation & Final Answer
    console.log(`Fire detections in Brazil (2007): ${count2007}`);
    console.log(`Fire detections in Brazil (2019): ${count2019}`);

    if (count2007 === null || count2019 === null) {
      console.log("C3"); // Calculation result is null/invalid
      return;
    }

    if (count2019 < count2007) {
      console.log("A"); // Yes, fewer fires in 2019
    } else {
      console.log("B"); // No, not fewer fires in 2019
    }

  } catch (error) {
    console.error("Analysis failed: ", error);
    console.log("D"); // General error or memory issue
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
